WINDOWS = [(.30, .70, .900, .965), (.25, .75, .890, .975), (.35, .65, .905, .955)]


def digits(png, psm):
    return subprocess.run(
        ["tesseract", png, "stdout", "--psm", str(psm),
         "-c", "tessedit_char_whitelist=0123456789"],
        capture_output=True, text=True,
    ).stdout


def folio(path, tag):
    im = Image.open(path)
