        png = f"{TMP}/{tag}_{j}.png"
        c.save(png)
        for psm in (7, 8, 6):
            for tok in re.findall(r"\d+", digits(png, psm)):
                if 1 <= len(tok) <= 3 and 1 <= int(tok) <= 260:
                    votes.append(int(tok))
    return Counter(votes).most_common(3)


for n in ["18-33-55", "18-33-58", "18-35-28", "18-36-41", "18-38-11", "18-39-48"]:
    p = f"{D}/2026-09-03_{n}.jpg"
    print(n, "->", folio(p, n), flush=True)

